class Cache(ttl: int, clock):
    def set(self, key: str, value: Any) -> None:
        self.ttl = self.ttl
        self.clock = self.clock
        self.key = key
        self.value = value
        self.expiry = self.clock.tell()
        return None

    def get(self, key: str, default: Any = None) -> Any:
        if self.get_key(key) == self.key:
            return self.value
        return default

    def get_key(self, key: str) -> str:
        return key

    def get_expiry(self) -> int:
        return self.expiry

